1	import 'dart:convert';
2	
3	import 'package:cerne/core/network/api_client.dart';
4	import 'package:cerne/core/network/error_mapper.dart';
5	import 'package:cerne/core/network/failure.dart';
6	import 'package:cerne/core/network/sse_frame.dart';
7	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
8	import 'package:cerne/features/chat/domain/entities/chat_session.dart';
9	import 'package:cerne/features/chat/domain/entities/chat_sessions_page.dart';
10	import 'package:cerne/features/chat/domain/entities/chat_stream_event.dart';
11	import 'package:fpdart/fpdart.dart';
12	
13	const _malformedChatFailure = ValidationFailure(
14	  message: 'Malformed chat response',
15	  requestId: '',
16	);
17	
18	/// The only class that calls `ApiClient.call('chat-sessions-create'/
19	/// 'chat-sessions-list'/'chat-messages-list', ...)` /
20	/// `ApiClient.sseStream('chat-messages-send'/'chat-messages-retry', ...)` and
21	/// parses the [ChatSession]/[ChatMessage]/[ChatStreamEvent] response shapes
22	/// (data-model.md, contracts/chat-repository.md).
23	class ChatRemoteDataSource {
24	  const ChatRemoteDataSource(this._apiClient);
25	
26	  final ApiClient _apiClient;
27	
28	  Future<Either<Failure, ChatSession>> createSession({
29	    required String title,
30	  }) async {
31	    final result = await _apiClient.call(
32	      'chat-sessions-create',
33	      method: 'POST',
34	      body: {'title': title},
35	    );
36	    return result.flatMap(_parseSession);
37	  }
38	
39	  Future<Either<Failure, ChatSessionsPage>> listSessions({
40	    String? cursor,
41	    int? limit,
42	  }) async {
43	    final queryParameters = <String, String>{
44	      'cursor': ?cursor,
45	      'limit': ?limit?.toString(),
46	    };
47	    final result = await _apiClient.call(
48	      'chat-sessions-list',
49	      method: 'GET',
50	      queryParameters: queryParameters.isEmpty ? null : queryParameters,
51	      unwrapData: false,
52	    );
53	    return result.flatMap(_parseSessionsPage);
54	  }
55	
56	  Future<Either<Failure, List<ChatMessage>>> listMessages(
57	    String sessionId,
58	  ) async {
59	    final result = await _apiClient.call(
60	      'chat-messages-list',
61	      method: 'GET',
62	      pathSegments: [sessionId],
63	      unwrapData: false,
64	    );
65	    return result.flatMap(_parseMessagesList);
66	  }
67	
68	  Stream<Either<Failure, ChatStreamEvent>> sendMessage({
69	    required String sessionId,
70	    required String content,
71	  }) {
72	    return _apiClient
73	        .sseStream(
74	          'chat-messages-send',
75	          method: 'POST',
76	          pathSegments: [sessionId],
77	          body: {'content': content},
78	        )
79	        .map(_mapFrame)
80	        .where((e) => e != null)
81	        .cast<Either<Failure, ChatStreamEvent>>();
82	  }
83	
84	  Stream<Either<Failure, ChatStreamEvent>> retryMessage({
85	    required String sessionId,
86	    required String userMessageId,
87	  }) {
88	    return _apiClient
89	        .sseStream(
90	          'chat-messages-retry',
91	          method: 'POST',
92	          pathSegments: [sessionId, userMessageId],
93	          body: const {},
94	        )
95	        .map(_mapFrame)
96	        .where((e) => e != null)
97	        .cast<Either<Failure, ChatStreamEvent>>();
98	  }
99	
100	  /// `null` for a frame this app ignores outright (`context`, research.md
101	  /// R2); every other frame maps 1:1 to a [ChatStreamEvent] or, for the
102	  /// backend-named `error` event, to `Left`.
103	  Either<Failure, ChatStreamEvent>? _mapFrame(
104	    Either<Failure, SseFrame> frameResult,
105	  ) {
106	    return frameResult.match(
107	      (failure) => Left(failure),
108	      (frame) {
109	        final decoded = jsonDecode(frame.data) as Map<String, dynamic>;
110	        return switch (frame.event) {
111	          'message_created' => Right(
112	            MessageCreated(
113	              userMessageId: decoded['userMessageId'] as String,
114	              assistantMessageId: decoded['assistantMessageId'] as String,
115	            ),
116	          ),
117	          'context' => null,
118	          'token' => Right(TokenReceived(decoded['delta'] as String)),
119	          'done' => Right(
120	            StreamDone(
121	              assistantMessageId: decoded['assistantMessageId'] as String,
122	              content: decoded['content'] as String,
123	              createdAt: DateTime.parse(decoded['createdAt'] as String),
124	            ),
125	          ),
126	          'error' => Left(ErrorMapper.fromResponse(decoded)),
127	          _ => null,
128	        };
129	      },
130	    );
131	  }
132	
133	  Either<Failure, ChatSession> _parseSession(Map<String, dynamic> data) {
134	    try {
135	      return Right(_parseSessionFields(data));
136	    } on TypeError {
137	      return const Left(_malformedChatFailure);
138	    } on FormatException {
139	      return const Left(_malformedChatFailure);
140	    }
141	  }
142	
143	  // `chat-sessions-list`'s full response body is `{"data": [...], "meta":
144	  // {"nextCursor": ...}}` — `ApiClient.call(..., unwrapData: false)` returns
145	  // it verbatim since the inner "data" here is an array, not an object.
146	  Either<Failure, ChatSessionsPage> _parseSessionsPage(
147	    Map<String, dynamic> body,
148	  ) {
149	    try {
150	      final sessions = (body['data'] as List<dynamic>)
151	          .map((s) => _parseSessionFields(s as Map<String, dynamic>))
152	          .toList();
153	      final meta = body['meta'] as Map<String, dynamic>;
154	      return Right(
155	        ChatSessionsPage(
156	          sessions: sessions,
157	          nextCursor: meta['nextCursor'] as String?,
158	        ),
159	      );
160	    } on TypeError {
161	      return const Left(_malformedChatFailure);
162	    } on FormatException {
163	      return const Left(_malformedChatFailure);
164	    }
165	  }
166	
167	  Either<Failure, List<ChatMessage>> _parseMessagesList(
168	    Map<String, dynamic> body,
169	  ) {
170	    try {
171	      final messages = (body['data'] as List<dynamic>)
172	          .map((m) => _parseMessageFields(m as Map<String, dynamic>))
173	          .toList();
174	      return Right(messages);
175	    } on TypeError {
176	      return const Left(_malformedChatFailure);
177	    } on FormatException {
178	      return const Left(_malformedChatFailure);
179	    }
180	  }
181	
182	  ChatSession _parseSessionFields(Map<String, dynamic> data) => ChatSession(
183	    id: data['id'] as String,
184	    title: data['title'] as String,
185	    personaSnapshot: ChatPersona.values.byName(
186	      data['personaSnapshot'] as String,
187	    ),
188	    userMessageCount: data['userMessageCount'] as int,
189	    lastUserMessageAt: (data['lastUserMessageAt'] as String?) == null
190	        ? null
191	        : DateTime.parse(data['lastUserMessageAt'] as String),
192	    createdAt: DateTime.parse(data['createdAt'] as String),
193	    updatedAt: DateTime.parse(data['updatedAt'] as String),
194	  );
195	
196	  ChatMessage _parseMessageFields(Map<String, dynamic> data) => ChatMessage(
197	    id: data['id'] as String,
