19	/// Fixed dark-green header (☰ + "Cerne" wordmark) and the live conversation
20	/// area — `ChatBloc`/`ChatSessionsBloc` are provided by `app_router.dart`'s
21	/// `/home` route builder (research.md R7), not here.
22	class HomeChatShellPage extends StatefulWidget {
23	  const HomeChatShellPage({super.key});
24	
25	  @override
26	  State<HomeChatShellPage> createState() => _HomeChatShellPageState();
27	}
28	
29	class _HomeChatShellPageState extends State<HomeChatShellPage> {
30	  late final StreamSubscription<void> _reauthSubscription;
31	
32	  @override
33	  void initState() {
34	    super.initState();
35	    // The one sanctioned cross-bloc touch point (research.md R3/R7) — lives
36	    // in this widget, never inside `ChatBloc` itself.
37	    _reauthSubscription = context.read<ChatBloc>().reauthRequired.listen((_) {
38	      if (!mounted) return;
39	      context.read<SessionBloc>().add(const AuthExpiredDetected());
40	    });
41	  }
42	
43	  @override
44	  void dispose() {
45	    _reauthSubscription.cancel();
46	    super.dispose();
47	  }
48	
49	  @override
50	  Widget build(BuildContext context) {
51	    return Scaffold(
52	      backgroundColor: DesignTokens.colorSurfaceBg,
53	      drawer: const AppDrawer(),
54	      onDrawerChanged: (isOpen) {
55	        if (isOpen) {
56	          context.read<ChatSessionsBloc>().add(const SessionsRefreshRequested());
57	        }
58	      },
59	      appBar: AppBar(
60	        backgroundColor: DesignTokens.colorPrimary,
61	        foregroundColor: DesignTokens.colorOnPrimary,
62	        title: Text(
63	          'Cerne',
64	          style: DesignTokens.textTitleLg.copyWith(color: DesignTokens.colorOnPrimary),
65	        ),
66	      ),
67	      body: BlocBuilder<ChatBloc, ChatState>(
68	        builder: (context, state) {
69	          final chatReady = state is ChatReady ? state : null;
70	          final List<ChatMessage> messages = chatReady?.messages ?? const [];
71	          final isOffline = chatReady?.isOffline ?? false;
72	          final canSend = chatReady?.canSend ?? false;
73	          final loadFailure = chatReady?.loadFailure;
74	
75	          return Column(
76	            children: [
77	              if (isOffline) const ChatOfflineBanner(),
78	              Expanded(
79	                child: loadFailure != null
80	                    ? _ChatLoadFailureView(
81	                        message: loadFailure.message,
82	                        onRetry: () => context.read<ChatBloc>().add(
83	                          ConversationSelected(chatReady!.sessionId!),
84	                        ),
85	                      )
86	                    : ListView.builder(
87	                        padding: const EdgeInsets.symmetric(
88	                          vertical: DesignTokens.spacingMd,
89	                        ),
90	                        itemCount: messages.length,
91	                        itemBuilder: (context, index) {
92	                          final message = messages[index];
93	                          return ChatMessageBubble(
94	                            message: message,
95	                            onRetryTap: () {
96	                              final userMessageId = index > 0
97	                                  ? messages[index - 1].id
98	                                  : null;
99	                              if (userMessageId == null) return;
100	                              context.read<ChatBloc>().add(
101	                                MessageRetryRequested(userMessageId),
102	                              );
103	                            },
104	                          );
105	                        },
106	                      ),
107	              ),
108	              ChatComposer(canSend: canSend),
109	            ],
110	          );
111	        },
112	      ),
113	    );
114	  }
115	}
116	
117	/// The "standard no-connection state" (Edge Cases) — a conversation selected
118	/// while offline/erroring with nothing cached for it to fall back to.
119	/// Mirrors `RecordsPage`'s own `_LoadFailureView` pattern.
120	class _ChatLoadFailureView extends StatelessWidget {
121	  const _ChatLoadFailureView({required this.message, required this.onRetry});
122	
123	  final String message;
124	  final VoidCallback onRetry;
125	
126	  @override
127	  Widget build(BuildContext context) {
128	    return Center(
129	      child: Padding(
130	        padding: const EdgeInsets.all(DesignTokens.spacingLg),
131	        child: Column(
132	          mainAxisSize: MainAxisSize.min,
133	          children: [
