import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:go_router/go_router.dart';

/// A plain [Drawer] widget (not a route) listing "Novo Chat", the
/// "CONVERSAS" side-menu list, "Meus Registros", and "Configurações" —
/// never disposes Home/Chat's `State` underneath (research.md R3).
class AppDrawer extends StatefulWidget {
  const AppDrawer({super.key});

  @override
  State<AppDrawer> createState() => _AppDrawerState();
}

class _AppDrawerState extends State<AppDrawer> {
  final _scrollController = ScrollController();
  late final StreamSubscription<void> _reauthSubscription;

  @override
  void initState() {
    super.initState();
    _scrollController.addListener(_maybeRequestNextPage);
    _reauthSubscription = context.read<ChatSessionsBloc>().reauthRequired.listen((_) {
      if (!mounted) return;
      context.read<SessionBloc>().add(const AuthExpiredDetected());
    });
  }

  void _maybeRequestNextPage() {
    if (!_scrollController.hasClients) return;
    final position = _scrollController.position;
    if (position.pixels >= position.maxScrollExtent - 200) {
      context.read<ChatSessionsBloc>().add(const SessionsNextPageRequested());
    }
  }

  @override
  void dispose() {
    _scrollController.dispose();
    unawaited(_reauthSubscription.cancel());
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Drawer(
      backgroundColor: DesignTokens.colorSurfaceElevated,
      child: SafeArea(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Padding(
              padding: const EdgeInsets.all(DesignTokens.spacingLg),
              child: Text('Cerne', style: DesignTokens.textHeadlineMd),
            ),
            const Divider(height: DesignTokens.dividerThickness),
            ListTile(
              leading: const Icon(Icons.add_comment_outlined, color: DesignTokens.colorPrimary),
              title: Text('Novo Chat', style: DesignTokens.textBodyLg),
              onTap: () {
                Navigator.of(context).pop();
                context.read<ChatBloc>().add(const NewConversationRequested());
              },
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(
                DesignTokens.spacingLg,
                DesignTokens.spacingMd,
                DesignTokens.spacingLg,
                DesignTokens.spacingSm,
              ),
              child: Text(
                'CONVERSAS',
                style: DesignTokens.textLabelMd.copyWith(color: DesignTokens.colorTextSecondary),
              ),
            ),
            Expanded(
              child: BlocBuilder<ChatSessionsBloc, ChatSessionsState>(
                builder: (context, state) {
                  return switch (state) {
                    ChatSessionsLoading() => const Center(child: CircularProgressIndicator()),
                    ChatSessionsLoadFailure() => Center(
                      child: TextButton(
                        onPressed: () => context
                            .read<ChatSessionsBloc>()
                            .add(const SessionsPageLoadRetried()),
                        child: const Text('Tentar novamente'),
                      ),
                    ),
                    ChatSessionsLoaded(
                      sessions: final sessions,
                      isLoadingMore: final isLoadingMore,
                      pageLoadFailure: final pageLoadFailure,
                    ) =>
                      ListView.builder(
                        controller: _scrollController,
                        itemCount:
                            sessions.length +
                            (isLoadingMore ? 1 : 0) +
                            (pageLoadFailure != null ? 1 : 0),
                        itemBuilder: (context, index) {
                          if (index < sessions.length) {
                            return _SessionTile(session: sessions[index]);
                          }
                          if (isLoadingMore) {
                            return const Padding(
                              padding: EdgeInsets.all(DesignTokens.spacingMd),
                              child: Center(child: CircularProgressIndicator()),
                            );
                          }
                          return _SessionsPageLoadFailureFooter(failure: pageLoadFailure!);
                        },
                      ),
                  };
                },
              ),
            ),
            const Divider(height: DesignTokens.dividerThickness),
            ListTile(
              title: Text('Meus Registros', style: DesignTokens.textBodyLg),
              onTap: () {
                Navigator.of(context).pop();
                context.push(AppRoutes.records);
              },
            ),
            ListTile(
              title: Text('Configurações', style: DesignTokens.textBodyLg),
              onTap: () {
                Navigator.of(context).pop();
                context.push(AppRoutes.settings);
              },
            ),
          ],
        ),
      ),
    );
  }
}

class _SessionsPageLoadFailureFooter extends StatelessWidget {
  const _SessionsPageLoadFailureFooter({required this.failure});

  final Failure failure;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      child: Column(
        children: [
          Text(
            failure.message,
            style: DesignTokens.textBodyMd.copyWith(color: DesignTokens.colorTextSecondary),
            textAlign: TextAlign.center,
          ),
          TextButton(
            onPressed: () =>
                context.read<ChatSessionsBloc>().add(const SessionsPageLoadRetried()),
            child: const Text('Tentar novamente'),
          ),
        ],
      ),
    );
  }
}

class _SessionTile extends StatelessWidget {
  const _SessionTile({required this.session});

  final ChatSession session;

  @override
  Widget build(BuildContext context) {
    final timestamp = (session.lastUserMessageAt ?? session.updatedAt).toLocal();
    final timestampLabel =
        '${timestamp.day.toString().padLeft(2, '0')}/${timestamp.month.toString().padLeft(2, '0')} '
        '${timestamp.hour.toString().padLeft(2, '0')}:${timestamp.minute.toString().padLeft(2, '0')}';

    return ListTile(
      title: Text(session.title, style: DesignTokens.textBodyLg, maxLines: 1, overflow: TextOverflow.ellipsis),
      subtitle: Text(
        timestampLabel,
        style: DesignTokens.textLabelMd.copyWith(color: DesignTokens.colorTextSecondary),
      ),
      onTap: () {
        Navigator.of(context).pop();
        context.read<ChatBloc>().add(ConversationSelected(session.id));
      },
    );
  }
}

