3	import 'package:equatable/equatable.dart';
4	
5	sealed class ChatState extends Equatable {
6	  const ChatState();
7	
8	  @override
9	  List<Object?> get props => [];
10	}
11	
12	/// Only while resuming `lastActiveSessionId` on `ChatStarted`.
13	class ChatLoading extends ChatState {
14	  const ChatLoading();
15	}
16	
17	/// Everything else — an existing conversation, the empty "Novo Chat" state,
18	/// or an outright load failure with nothing cached to fall back to — are all
19	/// one state shape so the screen never has to discard/rebuild its
20	/// `Scaffold`/`AppBar` switching between them.
21	class ChatReady extends ChatState {
22	  const ChatReady({
23	    required this.sessionId,
24	    required this.messages,
25	    required this.isOffline,
26	    required this.awaitingResponse,
27	    this.loadFailure,
28	  });
29	
30	  /// `null` = empty conversation, no session created yet (FR-010).
31	  final String? sessionId;
32	
33	  /// `[]` for an empty conversation.
34	  final List<ChatMessage> messages;
35	  final bool isOffline;
36	
37	  /// research.md R9 — gates the composer, true during a send/retry turn.
38	  final bool awaitingResponse;
39	
40	  /// Set only when selecting an existing session's history failed outright
41	  /// **and** nothing is cached for it (Clarification 3's no-content edge
42	  /// case).
43	  final Failure? loadFailure;
44	
45	  bool get canSend => !isOffline && !awaitingResponse && loadFailure == null;
46	
47	  static const _unset = Object();
48	
49	  ChatReady copyWith({
50	    String? sessionId,
51	    bool clearSessionId = false,
52	    List<ChatMessage>? messages,
53	    bool? isOffline,
54	    bool? awaitingResponse,
55	    Object? loadFailure = _unset,
56	  }) {
57	    return ChatReady(
58	      sessionId: clearSessionId ? null : (sessionId ?? this.sessionId),
59	      messages: messages ?? this.messages,
60	      isOffline: isOffline ?? this.isOffline,
61	      awaitingResponse: awaitingResponse ?? this.awaitingResponse,
62	      loadFailure: identical(loadFailure, _unset)
63	          ? this.loadFailure
64	          : loadFailure as Failure?,
65	    );
66	  }
67	
68	  @override
69	  List<Object?> get props => [
70	    sessionId,
71	    messages,
72	    isOffline,
73	    awaitingResponse,
74	    loadFailure,
75	  ];
76	}
